cd .skilled/skills/mcp-tooling/mcp-figma && python3 - <<'PY'
import re
files=["README.md","ROUTER.md","SKILL.md","assets/env-template.md","assets/utcp-figma-manual.md","references/figma-cli-reference.md","references/mcp-wiring.md","references/tool-surface.md"]
for f in files:
    lines=open(f).read().split('\n')
    block=[]; start=0
    def flush(block,start):
        if len(block)<2: return
        def cells(l):
            # split on unescaped pipes, ignoring leading/trailing
            parts=[]; cur=''; i=0
            while i<len(l):
                if l[i]=='\\' and i+1<len(l) and l[i+1]=='|':
                    cur+='|'; i+=2; continue
                if l[i]=='|':
                    parts.append(cur); cur=''; i+=1; continue
                cur+=l[i]; i+=1
            parts.append(cur)
            if parts and parts[0].strip()=='': parts=parts[1:]
            if parts and parts[-1].strip()=='': parts=parts[:-1]
            return parts
        h=len(cells(block[0]))
        for k,l in enumerate(block):
            c=len(cells(l))
            if c!=h:
                print(f"{f}:{start+k}: {c} cells, header has {h}: {l[:100]}")
    for idx,l in enumerate(lines,1):
        if l.lstrip().startswith('|'):
            if not block: start=idx
            block.append(l)
        else:
            flush(block,start); block=[]
    flush(block,start)
